head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL40213";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — emailChkMsg

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil40213.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.fnMsg();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40213.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Confirm_onclick
 * @description 「확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Confirm_onclick = async function(e){
    try {
        await scwin.confirm()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40213.btn_Confirm_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Confirm
 * @description Confirm 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Confirm = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Confirm",
        method: "post",
        action: action ?? "/outer/register.do",
        ref: "dma_ConfirmReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name confirm
 * @description confirm 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.confirm = async function () {
    if ($c.util.getComponent('ipt_emailChkNm').getValue()== null || ($c.util.getComponent('ipt_emailChkNm').getValue() == null ? '' : String($c.util.getComponent('ipt_emailChkNm').getValue())) === '') {
        await $c.win.alert('신규가입 신청시 작성한 이메일주소를 넣어주세요.');
        $c.util.getComponent("ipt_emailChkNm").focus();
        return;
    }
    if (scwin.fnEmailCheck($c.util.getComponent('ipt_emailChkNm').getValue())) {
        await $c.win.alert('이메일 형식이 틀렸습니다.');
        $c.util.getComponent("ipt_emailChkNm").focus();
        return;
    }
    $c.util.getComponent('dma_ConfirmReq').set('method', 'registerApplyForm');
    await scwin.tx_fn_Confirm('/outer/register.do');
};

/**
 * @method
 * @name fnEmailCheck
 * @description fn Email Check 처리
 * @param {*} email email
 * @returns {void}
 * @hidden N
 */
scwin.fnEmailCheck = function (email) {
    const mailexp = /^[_a-zA-Z0-9-\.]+@[\.a-zA-Z0-9-]+\.[a-zA-Z]+$/;
    if (!mailexp.test(email)) {
        return true;
    }
    return false;
};

/**
 * @method
 * @name fnMsg
 * @description fn Msg 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnMsg = async function () {
    await $c.win.alert((String(((dma_pageContext.get("emailChkMsg") ?? "")) == null ? '' : ((dma_pageContext.get("emailChkMsg") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("emailChkMsg") ?? "")) == null ? '' : ((dma_pageContext.get("emailChkMsg") ?? "")))));
};
